result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "src/chart.js", "content": "import * as THREE from "three";

/**
 * Builds a group of one box per datum.
 * Bar height = value / maxValue * maxHeight; bars are spaced 2 apart on x,
 * in data order. Each bar mesh is named `bar-<label>`.
 */
export function buildChart(data, { maxHeight = 10 } = {}) {
  const maxValue = Math.max(...data.map((d) => d.value));
  const group = new THREE.Group();

  data.forEach((datum, i) => {
    const height = (datum.value / maxValue) * maxHeight;
    const geometry = new THREE.BoxGeometry(1, height, 1);
    // Position so the bar sits on y=0: center at height/2.
    const material = new THREE.MeshBasicMaterial({ color: 0x3888ff });
    const bar = new THREE.Mesh(geometry, material);
    bar.name = `bar-${datum.label}`;
    bar.position.set(i * 2, height / 2, 0);
    group.add(bar);
  });

  return group;
}
"})
