result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "test/chart.test.js", "content": "import { describe, it, expect } from "vitest";
import * as THREE from "three";
import { buildChart } from "../src/chart.js";
import { data } from "../src/data.js";

const maxHeight = 10;

describe("buildChart", () => {
  const group = buildChart(data, { maxHeight });

  it("creates one bar per datum", () => {
    expect(group.children.length).toBe(4);
  });

  it("scales bar-Q4 to exactly maxHeight (within 1e-9)", () => {
    const bar = group.getObjectByName("bar-Q4");
    expect(bar).toBeDefined();
    const bbox = new THREE.Box3().setFromObject(bar);
    expect(Math.abs(bbox.max.y - bbox.min.y - maxHeight)).toBeLessThanOrEqual(1e-9);
  });

  it("scales bar-Q1 to 42/95 * maxHeight", () => {
    const bar = group.getObjectByName("bar-Q1");
    expect(bar).toBeDefined();
    const bbox = new THREE.Box3().setFromObject(bar);
    const expected = (42 / 95) * maxHeight;
    // BoxGeometry of height h has y-extent h; allow tiny float slack.
    expect(bbox.max.y - bbox.min.y).toBeCloseTo(expected, 9);
  });

  it("orders bars on x in data order", () => {
    data.forEach((datum, i) => {
      const bar = group.getObjectByName(`bar-${datum.label}`);
      expect(bar.position.x).toBe(i * 2);
    });
  });
});
"})
print(result)

result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "src/main.js", "content": "import * as THREE from "three";
import { buildChart } from "./chart.js";
import { data } from "./data.js";

const ready = document.getElementById("ready");

try {
  const renderer = new THREE.WebGLRenderer({ antialias: true });
  renderer.setSize(window.innerWidth, window.innerHeight);
  document.body.appendChild(renderer.domElement);

  const scene = new THREE.Scene();
  scene.background = new THREE.Color(0x101018);

  const camera = new THREE.PerspectiveCamera(
    50,
    window.innerWidth / window.innerHeight,
    0.1,
    100
  );
  camera.position.set(6, 7, 12);
  camera.lookAt(3, 4, 0);

  const group = buildChart(data);
  scene.add(group);

  const light = new THREE.DirectionalLight(0xffffff, 1);
  light.position.set(5, 10, 7);
  scene.add(light);
  scene.add(new THREE.AmbientLight(0xffffff, 0.4));

  renderer.render(scene, camera);

  ready.textContent = String(group.children.length);
} catch (err) {
  console.error(err);
}
"})
