result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "scripts/shot.mjs", "content": "// Headless page check: serves the project root over node:http, loads
// /public/index.html in bundled chromium (headless, no GPU), fails on any
// console error, waits for #ready to read "4", saves a screenshot.
import { createServer } from "node:http";
import { readFile } from "node:fs/promises";
import { extname, join, dirname } from "node:path";
import { fileURLToPath } from "node:url";
import { chromium } from "playwright";

const root = join(dirname(fileURLToPath(import.meta.url)), "..");
const port = 8971;

const MIME = {
  ".html": "text/html",
  ".js": "text/javascript",
  ".css": "text/css",
  ".png": "image/png",
};

const server = createServer(async (req, res) => {
  try {
    const url = new URL(req.url, `http://localhost:${port}`);
    let path = decodeURIComponent(url.pathname);
    if (path.endsWith("/")) path += "index.html";
    const file = join(root, path);
    if (!file.startsWith(root)) throw new Error("forbidden");
    const body = await readFile(file);
    res.writeHead(200, { "content-type": MIME[extname(file)] ?? "application/octet-stream" });
    res.end(body);
  } catch {
    res.writeHead(404);
    res.end("not found");
  }
});

await new Promise((resolve) => server.listen(port, resolve));

let exitCode = 0;
try {
  const browser = await chromium.launch({
    headless: true,
    args: ["--use-gl=swiftshader", "--enable-unsafe-swiftshader", "--disable-gpu"],
  });
  const page = await browser.newPage();

  const consoleErrors = [];
  page.on("console", (msg) => {
    if (msg.type() === "error") consoleErrors.push(msg.text());
  });
  page.on("pageerror", (err) => consoleErrors.push(String(err)));

  await page.goto(`http://localhost:${port}/public/index.html`, { waitUntil: "load" });
  await page.waitForSelector("#ready", { state: "visible", timeout: 15000 });

  const readyText = await page.textContent("#ready");
  if (readyText.trim() !== "4") {
    console.error(`#ready expected "4", got ${JSON.stringify(readyText)}`);
    exitCode = 1;
  }

  if (consoleErrors.length > 0) {
    for (const e of consoleErrors) console.error("console error:", e);
    exitCode = 1;
  }

  await mkdir(join(root, "out"), { recursive: true });
  await page.screenshot({ path: join(root, "out", "chart.png") });
  await browser.close();
} catch (err) {
  console.error(err);
  exitCode = 1;
} finally {
  server.close();
}

process.exit(exitCode);

import { mkdir } from "node:fs/promises";
"})
